:root {
  --cream: #f2e8d5;
  --bark: #6b4226;
  --river: #3a7d8c;
  --moss: #5a7a3a;
  --sand: #c9a96e;
  --ink: #2c1a0e;
  --light-bark: #c8a882;
}

article.rental-tag {
  background-color: var(--cream);
  border: 3px solid var(--bark);
  border-radius: 6px;
  width: 300px;
  padding: 0;
  margin: 40px auto;
  font-size: 14px;
  color: var(--ink);
  overflow: hidden;
}

.tag-header {
  background-color: var(--river);
  padding: 14px 16px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
  border-bottom: 3px solid var(--bark);
}

.tag-icon {
  font-size: 28px;
  line-height: 1;
}

.tag-title {
  font-size: 20px;
  font-weight: 800;
  color: var(--cream);
  margin: 0;
  line-height: 1.1;
}

.tag-sub {
  font-size: 11px;
  color: var(--light-bark);
  margin: 0;
  font-weight: 500;
  line-height: 1.2;
}

.tag-body {
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-bottom: 2px dashed var(--light-bark);
}

.tag-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.tag-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--river);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.tag-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
}

.tag-footer {
  padding: 10px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--cream);
}

.tag-badge {
  background-color: var(--moss);
  color: var(--cream);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 4px;
  letter-spacing: 0.04em;
}

.tag-price {
  font-size: 20px;
  font-weight: 800;
  color: var(--bark);
}
